import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第三册：培养技能 · Lesson 39 Nothing to worry about","description":"学习 不定式后置修饰与介词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 39 Nothing to worry about","description":"学习 不定式后置修饰与介词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 不定式后置修饰与介词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 38 The first calendar","link":"/life/english/new-concept/book-3/unit-02/lesson-038"},"next":{"text":"第三册：培养技能 · Lesson 40 Who's who","link":"/life/english/new-concept/book-3/unit-02/lesson-040"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 38 The first calendar","link":"/life/english/new-concept/book-3/unit-02/lesson-038"},"next":{"text":"第三册：培养技能 · Lesson 40 Who's who","link":"/life/english/new-concept/book-3/unit-02/lesson-040"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-039.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-039.md"}`),r={name:"life/english/new-concept/book-3/unit-02/lesson-039.md"};function l(i,e,s,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第三册-培养技能-·-lesson-39-nothing-to-worry-about" tabindex="-1">第三册：培养技能 · Lesson 39 Nothing to worry about <a class="header-anchor" href="#第三册-培养技能-·-lesson-39-nothing-to-worry-about" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 39 Nothing to worry about&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>从旅行中的风险判断学习表达安慰与依据。安慰不是删除风险信息，而是说明哪些条件已经检查、哪些仍需留意。学习不定式后置修饰名词和代词，特别注意介词保留问题，使“担心什么”“与谁交谈”等关系表达完整清晰。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>route</td><td>/ruːt/</td><td>n.</td><td>路线</td><td>a safe route</td></tr><tr><td>precaution</td><td>/prɪˈkɔːʃən/</td><td>n.</td><td>预防措施</td><td>take precautions</td></tr><tr><td>rough</td><td>/rʌf/</td><td>adj.</td><td>崎岖的</td><td>a rough track</td></tr><tr><td>reassure</td><td>/ˌriːəˈʃʊə/</td><td>v.</td><td>使安心</td><td>reassure a passenger</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>take precautions — 采取预防措施</li><li>keep an eye on — 留意某人或某事</li></ul><h2 id="语法讲解-不定式后置修饰与介词" tabindex="-1">语法讲解：不定式后置修饰与介词 <a class="header-anchor" href="#语法讲解-不定式后置修饰与介词" aria-label="Permalink to &quot;语法讲解：不定式后置修饰与介词&quot;">​</a></h2><p>名词或不定代词后可接不定式说明待完成的动作，例如 a route to follow。若被修饰词在不定式中相当于介词宾语，通常须保留介词，如 a person to talk to、nothing to worry about。若动词本身可直接带宾语，则不另加介词，如 a book to read。某些地点词如 place 后的介词可因惯用结构省略，但不应据此随意删除所有介词。此类短语常带潜在动作或用途，不能简单当作已发生的过去事实。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>We had a reliable guide to consult and a marked path to follow.</p></blockquote><p>我们有可靠向导可以咨询，也有标记清楚的小路可走。</p><p>consult 与 follow 都直接带宾语，因此不定式末尾无需额外介词；guide 与 path 分别为其对象。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>I need someone to speak 应表达为 someone to speak to，若意思是“需要一个说话者”，则原结构可能有不同含义。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 someone to talk to 与 a guide to consult，对比句尾有无介词；回听时检查 talk to 的 to 是否被吞掉。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>We have a clear map to follow. The ranger has checked the lower trail this morning. We should still watch for loose stones after the rain.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句向旅伴说明一次徒步准备，既给依据也保留注意事项。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>安慰建立在地图与检查上，最后一句避免把已有准备等同于零风险。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补全：There is nothing to worry ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> about</p><p><strong>解析：</strong> worry about 的介词保留。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句中的 to follow 需要再加 on 吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不需要。</p><p><strong>解析：</strong> follow 在此直接接 path 作宾语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>a map to check 表示地图已经检查了吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> 不定式可表示待检查的用途或任务。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：不定式后置修饰与介词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-038">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-040">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(r,[["render",l]]);export{u as __pageData,b as default};
